const player=new CourseVideo('player'),box=document.querySelector('#question'),progress=document.querySelector('#progress');let items=[],answered=new Set(),active=null,passed=0;
fetch('quizzes.json').then(r=>r.json()).then(q=>{items=q;progress.textContent='0 of '+q.length+' activities answered.';q.forEach(item=>{const b=document.createElement('button');b.textContent='Review '+item.id;b.type='button';b.className='reset';b.onclick=()=>{if(active)return;player.seek(item.time_seconds);present(item);};document.querySelector('#questionNav').append(b);});});
player.onTime(currentTime=>{if(active)return;const q=items.find(q=>!answered.has(q.id)&&currentTime>=q.time_seconds&&currentTime<q.time_seconds+1.5);if(q)present(q);});

function present(q){active=q;player.locked=true;player.pause();box.hidden=false;box.replaceChildren();const title=document.createElement('h3');title.textContent=q.question;const form=document.createElement('form'),options=document.createElement('div');options.className='options';q.options.forEach((text,i)=>{const label=document.createElement('label');label.className='option';const input=document.createElement('input');input.name='answer';input.type='radio';input.value=i;input.required=true;label.append(input,document.createTextNode(text));options.append(label);});const check=document.createElement('button');check.className='button';check.textContent='Check my answer';const feedback=document.createElement('p');feedback.className='feedback';feedback.hidden=true;const resume=document.createElement('button');resume.type='button';resume.textContent='Continue video →';resume.className='button';resume.hidden=true;const review=document.createElement('button');review.type='button';review.className='secondary';review.textContent='Review the explanation ↶';review.hidden=true;let correct=false;form.onsubmit=e=>{e.preventDefault();correct=+form.querySelector('input:checked').value===q.correct_index;feedback.textContent=(correct?'Correct. ':'Try revising your reasoning. ')+q.explanation;feedback.hidden=false;resume.hidden=false;review.hidden=correct;};function finish(jump){if(correct)passed++;answered.add(q.id);active=null;player.locked=false;box.hidden=true;player.seek(jump??(q.time_seconds+.3));progress.textContent=answered.size+' of '+items.length+' answered; '+passed+' correct on the last submitted attempt. Review and retry are encouraged.';player.play().catch(()=>{});}resume.onclick=()=>finish();review.onclick=()=>{const returnButton=document.createElement('button');returnButton.textContent='Return to question ↪';returnButton.className='button';returnButton.onclick=()=>{returnButton.remove();player.seek(q.time_seconds);present(q);};progress.after(returnButton);active=null;player.locked=false;box.hidden=true;player.seek(q.remediation_seconds);player.play().catch(()=>{});};form.append(options,check,feedback,resume,review);box.append(title,form);box.scrollIntoView({block:'nearest'});}
